svg.script:
//!export-start
let _pn_value1 = 0;
let _ps_label1 = 'A';
let _pn_value2 = 0;
let _ps_label2 = 'B';
let _pn_value3 = 0;
let _ps_label3 = 'C';
let _pn_value4 = 0;
let _ps_label4 = '';
let _pn_max = 100;
let _ps_centerLabel = 'Total';
let _ps_unit = '%';
let _pb_legend = false;
//!export-end

var __busyUntil = 0;

function toBool(v) {
    if (v === true || v === 1) return true;
    var s = String(v).toLowerCase();
    return s === 'true' || s === '1' || s === 'on';
}

function toNum(v) {
    if (v === true || v === 'true') return 1;
    if (v === false || v === 'false') return 0;
    var n = parseFloat(v);
    return isNaN(n) ? 0 : n;
}

function apply() {
    var preview = document.getElementById('ob_preview');
    if (preview && preview.parentNode) { preview.parentNode.removeChild(preview); }
    var el = document.getElementById('ob_el');
    if (!el) return;
    el.max = toNum(_pn_max);
    el.centerReadoutLabel = String(_ps_centerLabel);
    el.centerReadoutUnit = String(_ps_unit);
    el.legend = toBool(_pb_legend);
    var d = [];
    [[_ps_label1, _pn_value1], [_ps_label2, _pn_value2], [_ps_label3, _pn_value3], [_ps_label4, _pn_value4]].forEach(function (s) { if (String(s[0])) { d.push({ label: String(s[0]), value: toNum(s[1]) }); } });
    el.data = d;
}

function putValue(id, value) {
    if (id === '_pn_value1') { _pn_value1 = toNum(value); }
    if (id === '_ps_label1') { _ps_label1 = String(value); }
    if (id === '_pn_value2') { _pn_value2 = toNum(value); }
    if (id === '_ps_label2') { _ps_label2 = String(value); }
    if (id === '_pn_value3') { _pn_value3 = toNum(value); }
    if (id === '_ps_label3') { _ps_label3 = String(value); }
    if (id === '_pn_value4') { _pn_value4 = toNum(value); }
    if (id === '_ps_label4') { _ps_label4 = String(value); }
    if (id === '_pn_max') { _pn_max = toNum(value); }
    if (id === '_ps_centerLabel') { _ps_centerLabel = String(value); }
    if (id === '_ps_unit') { _ps_unit = String(value); }
    if (id === '_pb_legend') { _pb_legend = toBool(value); }
    apply();
}

function postValue(id, value) {
    // replaced at runtime: writes value to the tag bound to "id"
}

function fitBox() {
    var root = document.getElementById('ob_root');
    var fo = document.getElementById('ob_fo');
    var el = document.getElementById('ob_el');
    if (!root || !fo || !el) return;
    var w = parseFloat(root.getAttribute('width')) || 240;
    var h = parseFloat(root.getAttribute('height')) || 240;
    if (root.getAttribute('viewBox') !== '0 0 ' + w + ' ' + h) {
        root.setAttribute('viewBox', '0 0 ' + w + ' ' + h);
    }
    fo.setAttribute('width', w);
    fo.setAttribute('height', h);
    el.style.width = w + 'px';
    el.style.height = h + 'px';
    el.fixedHeight = h;
}

(function () {
    var root = document.getElementById('ob_root');
    fitBox();
    if (root && window.MutationObserver) {
        new MutationObserver(fitBox).observe(root, { attributes: true, attributeFilter: ['width', 'height'] });
    }
})();

apply();
